{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '괜찮은 모습으로만 있었던 거라서 그게 빠지면 관계도 같이 없어진다'고 반영한 것은 결함/수치심 스키마가 관계 맥락에서 작동하는 방식을 정확히 짚은 것. 배경의 성장 경험에서 '진짜 나는 결함이 있고 감춰야 하는 존재'라는 핵심 신념이 이 반영의 기원."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data", "/situations/2"],
      "relevance": "'사람들이 진짜 나를 알면 결국 떠날 것이다'라는 핵심 신념이 상담사의 '진짜 나를 기반으로 한 게 아니라는 확신'이라는 반영과 직접 연결. 배경의 친구 모임 배제 사례에서 이 신념이 상황적으로 확인되는 패턴을 보여줌."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/childhood_data"],
      "relevance": "'괜찮고 문제없는 모습만 보여줘야 한다'는 규칙이 상담사의 '괜찮은 모습으로만 있었던 거라서'라는 반영에 직접 대응. 배경에서 부모가 실수·힘든 모습을 보이면 '남들 앞에서 그러지 말라'고 한 경험이 이 규칙의 형성 맥락."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/3"],
      "relevance": "'괜찮은 모습만 유지하면 사람들이 곁에 둘 것'이라는 긍정 가정이 상담사의 '괜찮은 모습을 유지할수록 관계가 진짜 나를 기반으로 한 게 아니라는 확신이 더 강해진다'는 역설적 반영의 전제. 배경의 야간 반추 후 다음 날 더 밝게 행동하는 패턴이 이 가정의 반복적 작동 사례."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/2"],
      "relevance": "'부족하거나 힘든 모습을 보이면 사람들이 실망해서 떠날 것'이라는 부정 가정이 내담자의 '서서히 연락이 줄어들다가 아무 일도 없었던 것처럼 되는 게 무섭다'는 표현과 연결. 배경의 SNS 모임 배제 사례에서 이 가정이 자동적으로 작동하는 방식 확인."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/3"],
      "relevance": "'항상 밝고 문제없는 모습을 유지하며 힘든 감정은 혼자 삭힌다'는 대처 방식이 상담사의 반영에서 직접 언급된 '괜찮은 모습으로만 있었던'이라는 행동 패턴에 해당. 배경의 야간 반추 후 다음 날 더 밝게 행동하는 사례가 이 대처의 구체적 발현."
    }
  ]
}

